head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > tooltipDisplay]<br/>Cell 값이 잘려서 표시될때 마우스 오버 시 Cell 값을 툴팁으로 표시할지 설정합니다.",
    "validation" : [
        "툴팁 대상은 Body 와 Footer 영역의 Cell 이며, Header 영역의 툴팁은 tooltipHeader 속성으로 설정합니다.",
        "true 설정 시, Cell 값이 잘려서 표시될때 Cell 영역에 마우스 오버 시 Cell 값을 툴팁으로 표시합니다.",
        "false 설정 시, Cell 값 잘림 여부와 관계없이 Cell 영역에 마우스를 오버해도 Cell 값이 툴팁으로 표시되지 않습니다.",
        "미설정 시, Cell 값 잘림 여부와 관계없이 Cell 영역에 마우스를 오버해도 Cell 값이 툴팁으로 표시되지 않습니다.",
        "Body 와 Footer 영역의 Cell 에 적용되며 Cell 값이 ''(Empty String)인 경우에는 툴팁이 표시되지 않습니다.",
        "RowNum, RowStatus Column 의 Cell 에서는 툴팁이 표시되지 않습니다.",
        "inputType='secret','custom','spinner' 인 Cell 은 툴팁이 표시되지 않습니다.",
        "inputType='checkbox','radio' 인 Cell 은 label 값이 있어야 툴팁이 표시됩니다.",
        "tooltipDisplay=true 일때 tooltipShowAlwaysColumns 에 설정된 Column 이 tooltipDisplayColumn 에 없으면 적용되지 않습니다.",
        "tooltipDisplay=true 일때 tooltipDisplayColumn, tooltipShowAlwaysColumns 에 설정된 Column 이 tooltipHideInputType 에 해당하면 적용되지 않습니다.",
        "tooltipDisplay=true 일때 tooltipShowAlwaysColumns, tooltipShowAlways 속성은 tooltipDisplayColumn, tooltipHideInputType 을 통과한 Column 또는 Cell 에 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_tooltipDisplay 초기값 보관 (true 설정 케이스로 시작)
    scwin.gVar = { "cTooltipDisplay": "true" };

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - tooltipDisplay 검증용 커스텀 GridView 를 인라인 정의로 생성한다.
//    (기본 createBasicGridView 는 text 컬럼 4개라 잘린/짧은/빈/특수 inputType/Footer/B5 를 한번에 확인 불가)
//  - 고정 전제 : rowNumVisible/rowStatusVisible=true (RowNum/RowStatus Cell 미표시 검증)
//                w2:footer 영역 정의 (Footer Cell 툴팁 검증)
//  - Body/Footer 컬럼 구성 (좁은 폭으로 긴 값 잘림 유도)
//      col_long   : 긴 값(잘림) text       -> true 면 마우스오버 툴팁 표시
//      col_short  : 짧은 값(미잘림) text    -> true 여도 잘리지 않으면 미표시
//      col_empty  : 빈 값('') text          -> 미표시 (Body/Footer 빈문자열)
//      col_link   : 긴 URL link             -> 잘리면 표시 (B5 HideInputType 대상)
//      col_radio  : 긴 label radio          -> label 값 있으면 표시
//      col_secret : 긴 값 secret            -> 미표시
//      col_custom : 긴 값 custom            -> 미표시
//      col_spin   : 긴 값 spinner           -> 미표시
//  - B5 우선순위 데모 (tooltipDisplay=true 일때만 연관 속성 적용)
//      tooltipDisplayColumn      = "col_long,col_short,col_link"   (이 세 Column 만 툴팁 후보)
//      tooltipShowAlwaysColumns  = "col_short,col_empty"           (col_empty 는 DisplayColumn 에 없어 미적용)
//      tooltipHideInputType      = "link"                          (link Cell 미적용)
//                                                                  → col_link 는 긴 URL 이라 원래 잘리면 표시되지만
//                                                                    HideInputType=link 로 미표시 (실효 관찰).
//                                                                    col_long(text)은 HideInputType 미해당 → 여전히 표시(대비).
//      tooltipShowAlways         = false                           (전체 항상표시는 아님, ShowAlwaysColumns 만 시연)
scwin.comp_init = async function () {
    // con 현재값 반영 (Target 재생성 버튼이 comp_init 재호출)
    scwin.gVar.cTooltipDisplay = con_tooltipDisplay.getValue();   // "true" / "false" / "" (미설정)

    // 동적 생성용 네임스페이스 (페이지 scope 에서 공통 strNameSpace 가 비어있을 수 있어 로컬 정의)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    let dispMsg = (scwin.gVar.cTooltipDisplay === "") ? "미설정(기본 false)" : scwin.gVar.cTooltipDisplay;
    $c.gcm.createLabel('label="[전제] tooltipDisplay=' + dispMsg + ' / RowNum,RowStatus,Footer 표시.\n[전제] B5 연관속성(true 일때만 적용): tooltipDisplayColumn=(col_long,col_short,col_link), tooltipShowAlwaysColumns=(col_short,col_empty), tooltipHideInputType=(link).\n[절차] Body/Footer Cell 에 마우스를 오버하여 툴팁 표시 여부를 확인하세요.\n[확인] true: DisplayColumn 인 col_long(잘림) 만 잘림 시 표시. col_short 는 ShowAlwaysColumns 라 짧아도 항상 표시. col_link 는 긴 URL 이라 원래 잘리면 표시되지만 HideInputType=link 라 미표시(=DisplayColumn 통과 후 HideInputType 으로 차단). col_empty 는 DisplayColumn 에 없어 ShowAlwaysColumns 미적용+미표시. RowNum/RowStatus 미표시. false/미설정: 모두 미표시."', '', 'label1');

    // dataList 생성 ($p.dynamicCreate 가 아닌 $p.data.create 로 생성)
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col_long" name="col_long"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_short" name="col_short"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_empty" name="col_empty"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_link" name="col_link"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_radio" name="col_radio"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_secret" name="col_secret"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_custom" name="col_custom"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_spin" name="col_spin"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    scwin.dlt_bind.setJSON([
        { "col_long": "서울특별시 강남구 테헤란로 152 강남파이낸스센터 23층", "col_short": "서울", "col_empty": "", "col_link": "https://www.example.com/finance/portal/dashboard?region=seoul&branch=gangnam&tab=summary", "col_radio": "1", "col_secret": "P@ss12345", "col_custom": "기업금융사업본부 디지털전략기획팀", "col_spin": "12345" },
        { "col_long": "부산광역시 해운대구 센텀중앙로 79 센텀사이언스파크 18층", "col_short": "부산", "col_empty": "", "col_link": "https://www.example.com/finance/portal/dashboard?region=busan&branch=centum&tab=summary", "col_radio": "0", "col_secret": "P@ss67890", "col_custom": "개인고객사업본부 영업지원팀", "col_spin": "67890" }
    ], false);

    // tooltipDisplay : con 값에 따라 설정/미설정 (미설정 시 속성 자체를 제외하여 기본값 false 동작 확인)
    let dispAttr = (scwin.gVar.cTooltipDisplay === "") ? "" : 'tooltipDisplay="' + scwin.gVar.cTooltipDisplay + '" ';

    // B5 연관 속성은 tooltipDisplay=true 일때만 의미가 있으므로 true 케이스에서만 부여
    let b5Attr = "";
    if (scwin.gVar.cTooltipDisplay === "true") {
        b5Attr  = 'tooltipDisplayColumn="col_long,col_short,col_link" ';
        b5Attr += 'tooltipShowAlwaysColumns="col_short,col_empty" ';
        b5Attr += 'tooltipHideInputType="link" ';
        b5Attr += 'tooltipShowAlways="false" ';
    }

    // 커스텀 GridView 인라인 정의
    //  - 좁은 컬럼 폭으로 긴 값 잘림(truncation) 유도, w2:footer 영역 포함
    //  - B2(RowNum/RowStatus Cell 미표시) 의미화용 설정 :
    //      RowNum   : rowNumWidth="20" 으로 컬럼을 매우 좁게 + onpageload 에서 setStartRowNumber 로
    //                 시작번호를 큰 값(예 99999)으로 올려 행번호 자릿수가 20px 폭을 넘게 함
    //                 → RowNum Cell 이 "잘려서 표시될 조건" 성립. 그래도 hover 시 툴팁 미표시여야 함.
    //      RowStatus: rowStatusVisible 는 행 상태를 "아이콘"으로만 렌더(텍스트 아님, @description '아이콘으로 표시')
    //                 → 텍스트 잘림(clientW<scrollW) 조건을 구조적으로 만들 수 없음. rowStatusWidth="14" 로
    //                   최소폭 + 행을 수정/삽입 상태(U/C)로 만들어 상태 아이콘이 실제로 렌더되게 한 뒤
    //                   hover → 툴팁 미표시를 확인한다. (RowStatus 는 아이콘만이라 잘림 자체가 불가함을 명시)
    let strTarget = '<w2:gridView ' + ns + ' ' + dispAttr + b5Attr + 'rowNumVisible="true" rowNumWidth="20" rowStatusVisible="true" rowStatusWidth="14" dataList="data:dlt_bind" checkAllType="false" id="" style="width:760px;height:280px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="70" inputType="text" id="col_long" value="주소"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_short" value="지역"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_empty" value="비고"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_link" value="링크"></w2:column>';
    strTarget += '<w2:column width="60" inputType="radio" id="col_radio" value="구분"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_secret" value="비밀번호"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_custom" value="소속"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_spin" value="수량"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="70" inputType="text" id="col_long" dataList="col_long"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_short" dataList="col_short"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="col_empty" dataList="col_empty"></w2:column>';
    strTarget += '<w2:column width="60" inputType="link" id="col_link" dataList="col_link"></w2:column>';
    strTarget += '<w2:column width="60" inputType="radio" id="col_radio" dataList="col_radio"></w2:column>';
    strTarget += '<w2:column width="60" inputType="secret" id="col_secret" dataList="col_secret"></w2:column>';
    strTarget += '<w2:column width="60" inputType="custom" id="col_custom" dataList="col_custom" displayFunction="scwin.customDisplay"></w2:column>';
    strTarget += '<w2:column width="60" inputType="spinner" id="col_spin" dataList="col_spin"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="70" inputType="text" id="ft_long" value="합계 1,234,567,890 원 (전 영업점 기준)"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_short" value="소계"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_empty" value=""></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_link" value=""></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_radio" value=""></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_secret" value=""></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_custom" value=""></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="ft_spin" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    let grp_comp = document.querySelector('.tc_group_basic');
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // [B2 의미화] RowNum 시작번호를 큰 값으로 올려 행번호 자릿수가 rowNumWidth(20px) 폭을 넘게 함
    //   (인덱스 99998 → 화면 표시 99999, 100000, 100001) → RowNum Cell 잘림 조건 성립.
    // [B2 의미화] 행을 수정/삽입 상태로 만들어 RowStatus 아이콘이 실제로 렌더되게 함
    //   (1행 setCellData → 상태 U(갱신), 끝행 insertRow → 상태 C(삽입)). RowStatus 는 아이콘만이라
    //    텍스트 잘림은 구조적으로 불가하나, 상태 아이콘이 표시된 Cell 에서도 hover 시 툴팁 미표시임을 확인.
    scwin.target1.setStartRowNumber(99998);
    scwin.dlt_bind.setCellData(0, "col_short", "강원");   // 1행 값 변경 → rowStatus "U"
    let newIdx = scwin.dlt_bind.insertRow();               // 끝에 행 삽입 → rowStatus "C"
    scwin.dlt_bind.setRowJSON(newIdx, { "col_long": "인천광역시 연수구 송도과학로 32 인천글로벌캠퍼스 5층", "col_short": "인천", "col_empty": "", "col_link": "https://www.example.com/finance/portal/dashboard?region=incheon&branch=songdo&tab=summary", "col_radio": "1", "col_secret": "P@ssABCDE", "col_custom": "리스크관리본부 신용평가팀", "col_spin": "33333" }, true);

    // 클릭 시 현재 표시된 툴팁 정보를 return 영역에 출력하기 위한 클릭 리스너 설치
    scwin.attachTooltipClick();
}



// Body/Header/Footer Cell 클릭 시 "현재 표시된" 툴팁 정보를 return 영역에 출력
//  - 셀에 마우스를 오버해 툴팁(잘린 Cell 값)이 표시된 상태에서 그 영역을 클릭하면 호출된다.
//  - 타이밍 주의 : 엔진은 셀 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫는다(display:none).
//    따라서 클릭의 "캡처(capture) 단계" 리스너로 잡아야 툴팁이 아직 display:block 으로 살아있어
//    $c.gcm.getTooltipInfo 가 '[class*="_tooltip"]' 의 textContent/display 를 정상 출력한다.
//    (그리드의 oncellclick 이벤트는 버블/기본 처리 단계라 이 시점엔 이미 툴팁이 닫혀 사용 불가)
//  - 리스너를 그리드 DOM 엘리먼트에 걸어 Body/Header/Footer 클릭을 모두 커버한다.
//  - 마우스오버만 해서는 출력되지 않으며, 클릭 시점에 현재 hover 로 표시된 툴팁 값이 캡처된다.
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }

    // Target 재생성 시 이전 리스너 정리 (이전 엘리먼트가 제거되었더라도 핸들러 참조만 갱신)
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function () {
        // 캡처 단계 : 엔진이 툴팁을 닫기 전이므로 현재 표시된 툴팁이 살아있다.
        $c.gcm.getTooltipInfo(wf_body_bottom);
    };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);   // capture 단계
};



// custom inputType 표시 함수 (col_custom Body Cell 표시값)
scwin.customDisplay = function (value) {
    return value;
};
